    description: "月季为常绿或半常绿灌木，高可达 2 m，茎直立或蔓生，小枝上生有弯曲的皮刺；奇数羽状复叶，小叶 3–5 枚，宽卵形，边缘具锐锯齿，叶面光亮。花单生或数朵簇生于枝顶，花径 4–10 cm，有红、粉、白、黄、紫等色，重瓣或半重瓣，多数具香气；蔷薇果卵圆形，成熟时橙红色。\n\n月季原产中国，栽培历史逾两千年，喜光、喜温暖，耐寒性因品种而异，适宜疏松肥沃、排水良好的微酸性土壤。月季花期极长，在适宜条件下可四季开花，故有“月月红”之称；18 世纪中国月季传入欧洲，与当地蔷薇杂交育成现代月季，成为世界最重要的观赏花卉之一。花可提取香精、制花茶，根与叶可入药，月季也是北京、天津等城市的市花。",
