    description: "牡丹为落叶灌木，高可达 2 m，茎直立，树皮灰褐色，分枝粗壮；叶片为二回三出复叶，顶生小叶宽卵形，常 3 裂，表面绿色、背面淡绿。花期 4–5 月，花单生于枝顶，花径可达 25 cm，有单瓣、重瓣之分，花色有红、粉、白、黄、紫、绿等，花形端庄、香气清雅；蓇葖果成熟时开裂，种子黑色。\n\n牡丹原产中国西北部及秦岭、大巴山一带，野生类型生于海拔 1000–2000 m 的山地灌丛，栽培历史逾一千五百年，现以河南洛阳、山东菏泽最为著名。牡丹喜光、耐寒、怕积水，适宜深厚肥沃、排水良好的沙壤土；分株、嫁接与播种均可繁殖。根皮即中药“丹皮”，可清热凉血；牡丹文化底蕴深厚，被视为富贵吉祥的象征，唐代以来“唯有牡丹真国色”的诗句流传至今。",
