    description: "枸骨为常绿灌木或小乔木，高可达 3 m，树皮灰白色，小枝有棱；叶片革质，四角状长圆形，顶端具 3 枚硬刺，两侧各有 1–2 枚刺齿，深绿色有光泽，老叶上的刺有时退化。花期 4–5 月，聚伞花序生于叶腋，花小、黄绿色；果实为核果，球形，成熟时鲜红色，直径 8–10 mm，可宿存至翌年春季。\n\n枸骨原产中国长江流域及以南地区，喜光、稍耐阴，喜温暖湿润，耐寒性较强，适宜疏松肥沃、排水良好的微酸性土壤。因叶形奇特、红果越冬，欧美常称其为“中国冬青”，是圣诞花环与装饰的传统材料；在中国，枸骨枝叶四季常青、果色红艳，常被栽于庭院，寓意吉祥。叶、根与果实可入药，中药“枸骨叶”能清热养阴，但果实有小毒，不可随意食用。",
