    description: "瑞香为常绿灌木，高可达 1.5 m，枝条粗壮，树皮灰褐色；叶片互生，长椭圆形，革质，边缘全缘并微反卷，表面深绿。花期 2–4 月，头状花序顶生，由数朵至十余朵小花组成，花被筒状、4 裂，外面紫红色、内面白色，香气浓郁；果实为核果，卵形，成熟时红色，但结果较少。\n\n瑞香原产中国长江流域及华南地区，喜温暖湿润、半阴环境，忌强光暴晒与高温，适宜疏松肥沃、排水良好的酸性土壤，不耐寒，北方多盆栽。它是中国传统名花，栽培历史逾千年，因花期正值春节前后，被视为吉祥之花；花朵虽小，但香气浓烈，可提取香精。瑞香的根、茎与叶可入药，但全株有毒，汁液接触皮肤可能引起过敏，修剪时宜戴手套。",
