    description: "金银花为常绿或半常绿缠绕藤本，茎长达 9 m，幼枝暗红色、密被短柔毛；叶片对生，卵形至椭圆形，全缘，两面被毛。花期 4–6 月，花成对生于叶腋，花冠唇形，长 3–5 cm，初开白色、次日转为金黄色，黄白相间，故得名“金银花”，香气清雅；浆果球形，成熟时黑色。\n\n金银花原产中国、朝鲜半岛及日本，中国南北各地常见，喜光、耐寒、耐旱，对土壤要求不严，在山坡、灌丛与路旁都能生长。花蕾未开放时采收干燥，即为中药“金银花”，能清热解毒、疏散风热，是银翘解毒片等中成药的原料；藤茎入药称“忍冬藤”。金银花适应性强、攀爬迅速，既是药用植物，也是庭院篱垣与棚架的绿化藤本。",
    habitat: "海拔 1500 米以下的山坡灌丛、林缘与路旁，喜光耐寒，适应性强",
