    description: "爬山虎为落叶木质藤本，茎长达 20 m 以上，卷须短而多分枝，顶端具圆形吸盘，能吸附在墙面、岩石与树干上。叶片宽卵形，常 3 裂，边缘具粗齿，叶柄长；花期 6–7 月，花小、黄绿色，聚伞花序生于短枝；浆果球形，成熟时紫黑色，被白粉，内含 1–2 粒种子。\n\n爬山虎原产中国、朝鲜半岛及日本，中国南北各地常见，攀附于墙面、崖壁与树干上生长，喜光、耐寒、耐旱，对土壤要求不严。秋季叶片变为鲜红或橙红，是优良的垂直绿化与秋色叶藤本；密集的叶幕能遮挡阳光、降低墙面温度，被称为“绿色空调”。根茎可入药，有祛风除湿之效；由于吸盘固着牢固，爬山虎常被用于旧墙与护坡绿化。",
