    description: "南天竹为常绿灌木，高可达 2 m，茎直立、少分枝，幼枝红色；叶片为二至三回羽状复叶，小叶椭圆状披针形，革质，全缘，入秋后逐渐转为红色。花期 5–7 月，圆锥花序顶生，花小、白色，花瓣 6 枚；浆果球形，直径约 8 mm，成熟时鲜红色，可宿存至翌年春季，内含 2 粒种子。\n\n南天竹原产中国长江流域及日本，喜温暖湿润、半阴环境，较耐寒，适宜疏松肥沃、排水良好的微酸性土壤。因枝干挺拔似竹、红果经冬不落，常被栽植于庭院、假山旁与花境中，也是传统盆景与插花材料，寓意“天竹报福”“红红火火”。根、茎与果实可入药，但全株有毒，果实毒性较强，不可食用；栽培中注意避免儿童误食。",
