    description: "紫荆为落叶灌木或小乔木，高可达 5 m，树皮灰褐色、平滑；叶片心形，互生，全缘，表面光滑，叶柄细长。花期 3–4 月，先花后叶，花紫红色、蝶形，数朵至十余朵簇生于老枝和主干上，密密麻麻，故有“满条红”之称；荚果扁平、线形，长 5–15 cm，成熟时深褐色，内含 2–6 粒种子。\n\n紫荆原产中国华北、华东、中南及西南地区，中国各地广泛栽培，喜光、耐寒、耐旱，对土壤要求不严，在庭院与公园中常见。早春紫花满枝、花后心形叶片翠绿，观赏效果极佳，是北方与江南常见的早春观花灌木；树皮与花可入药，有活血通经之效；木材可供细木工用。紫荆在香港地区是重要的文化符号，香港区旗与区徽上的花朵即为洋紫荆，但洋紫荆与北方常见的紫荆并非同种植物。",
