    description: "三角梅为常绿攀援灌木，茎粗壮，枝条常拱形下垂，具腋生刺；叶片互生，卵形至椭圆形，全缘。花期长，在温暖地区几乎全年开花，花小、黄绿色，三朵聚生于三枚色彩鲜艳的苞片中，苞片呈紫红、粉、橙、白等色，形似花瓣，是主要的观赏部位；果实为瘦果，少见结实。\n\n三角梅原产南美洲巴西、秘鲁等地，中国广东、广西、福建、海南、云南等地广泛栽培，喜高温、光照充足，耐旱、耐修剪，适宜疏松肥沃、排水良好的土壤。因花期长、花色艳丽、适应性强，常被用于阳台、围墙、天桥与公园的立体绿化，也是南方城市常见的市花；厦门、深圳、珠海等城市均以三角梅为市花或重要景观植物。三角梅的苞片色彩来自细胞中的色素，日照越充足、开花越繁盛。",
    habitat: "海拔 800 米以下的热带亚热带地区，喜高温、光照充足，耐旱",
