    summary: "中国南方常见的常绿灌木，叶片革质光亮、聚生枝顶，初夏开白色小花、香气浓郁，是优良的绿篱与观赏植物。",
    description: "海桐为常绿灌木，高可达 3 m，树冠圆球形，枝条稠密；叶片聚生于枝顶，倒卵形，革质，边缘全缘并微反卷，表面深绿有光泽。花期 5–7 月，伞形花序顶生，花白色后转淡黄，花径约 1 cm，花瓣 5 枚，芳香浓郁；蒴果卵圆形，成熟时开裂，露出鲜红色种子，观赏期长。\n\n海桐原产中国福建、浙江、江苏、广东、台湾等地及日本、朝鲜半岛，中国长江流域以南广泛栽培，喜光、也耐半阴，耐寒性较强，适宜疏松肥沃、排水良好的土壤。因抗污染能力强、耐修剪，常被用作城市绿篱、厂区绿化与海岸防护林；叶片常绿光亮、花香浓郁，也是优良的庭园观赏灌木。根与叶可入药，有祛风活血之效；种子可榨油。海桐的俗名“七里香”与另一种同名植物容易混淆，需注意区分。",
    habitat: "海拔 800 米以下的海岸、山坡与城市绿地，喜光耐阴，抗污染",
    distribution: "中国福建、浙江、江苏、广东、台湾等地，日本、朝鲜半岛也有分布",
