    summary: "中国南方常见的常绿灌木或小乔木，春季新叶鲜红、老叶翠绿，初夏开白色小花，是城市绿化与绿篱常用树种。",
    description: "石楠为常绿灌木或小乔木，高可达 12 m，树皮灰褐色；叶片互生，长椭圆形至倒卵状椭圆形，革质，边缘具细锯齿，春季新叶鲜红，后转深绿。花期 4–5 月，复伞房花序顶生，花白色、密集，花径约 1 cm，气味特殊，常招引蝇类传粉；果实为小梨果，球形，成熟时红色，冬季宿存。\n\n石楠原产中国陕西、甘肃至长江流域以南各地，也见于日本、印度尼西亚，中国南方城市广泛栽培，喜光、耐阴、耐修剪，对土壤要求不严。春季红叶、夏季白花、秋冬红果，观赏期长，常被修剪成绿篱、球状或造型树，是城市道路与公园的常见绿化树种；木材可制器具，叶与根可入药。石楠花开时特殊的气味常被误认为“臭味”，这是它依靠蝇类传粉的适应特征。",
