    description: "火棘为常绿灌木，高可达 3 m，枝条拱形下垂，侧枝先端常成刺状；叶片互生，倒卵形至长椭圆形，边缘具细锯齿。花期 3–5 月，复伞房花序生于短枝顶，花白色、密集，花径约 1 cm；果实为小梨果，球形，成熟时橙红至深红色，直径约 5 mm，成串密集地挂在枝头，可从秋季宿存至翌年春季。\n\n火棘分布于中国陕西、甘肃至长江流域以南及西南地区，也见于印度、缅甸，喜光、耐旱、耐瘠薄，适应性强，常生于山坡、路旁与灌丛。秋冬红果满枝，是优良的观赏灌木与盆景材料；果实富含维生素 C 与糖类，可生食或酿酒，灾荒年代曾作为救荒食物，故有“救军粮”之称；根、叶与果实可入药。火棘耐修剪，也是绿篱与水土保持的常用树种，在西南山区常见成片分布。",
    habitat: "海拔 2000 米以下的山坡、路旁与灌丛，喜光耐旱耐瘠薄",
    distribution: "中国陕西、甘肃至长江流域以南及西南地区，印度、缅甸也有分布",
