    summary: "中国常见的早春观花灌木，花朵紧贴枝干开放、红艳夺目，果实即中药“木瓜”，是庭院与盆景的传统花木。",
    description: "贴梗海棠为落叶灌木，高可达 2 m，枝条有刺；叶片卵形至椭圆形，边缘具尖锐锯齿，托叶肾形。花期 3–5 月，先花后叶或花叶同放，花 3–5 朵簇生于两年生枝上，花梗极短、几乎贴着枝干开放，故得名“贴梗海棠”；花冠红色、粉色或白色，花径 3–5 cm。果实为梨果，球形或卵球形，成熟时黄绿色，果皮皱缩，故又称“皱皮木瓜”。\n\n贴梗海棠原产中国陕西、甘肃、四川、贵州、云南、广东等地，中国南北各地广泛栽培，喜光、耐寒、耐旱，适宜深厚肥沃、排水良好的土壤。早春开花、花艳似锦，是庭院、花境与盆景的优良树种；果实可入药，中药“木瓜”即其干燥果实，能舒筋活络、和胃化湿；果实还可加工果酱与果酒。贴梗海棠与海棠花、垂丝海棠同属蔷薇科，但贴梗海棠花梗极短、花朵紧贴枝干，是最容易辨认的一种。",
    habitat: "海拔 2000 米以下的山坡、灌丛与庭院，喜光耐寒耐旱",
