    description: "一品红为常绿灌木，高可达 3 m，全株含白色乳汁；叶片互生，卵状椭圆形至披针形，绿色。花期 11 月至翌年 3 月，顶生杯状聚伞花序，花序下方有多枚苞片，在短日照条件下转为鲜红色，也有粉、白、黄等品种，苞片形似花瓣，是主要的观赏部位；真正的花小、黄绿色，生于苞片中央。蒴果成熟时开裂。\n\n一品红原产墨西哥及中美洲，中国各地广泛栽培，喜光、喜温暖湿润，适宜疏松肥沃、排水良好的土壤，不耐寒，北方多作盆栽。因苞片鲜红、花期适逢圣诞与元旦，是西方圣诞节最重要的装饰植物，被称为“圣诞红”；中国南方可露地栽培作花坛与庭院布景。一品红的白色乳汁有毒，接触皮肤可能引起过敏，误食会引起呕吐，栽培与观赏时需注意，尤其要避免儿童误食。",
