    summary: "热带地区常见的落叶小乔木，花朵外白内黄、形似鸡蛋，香气清雅，是东南亚寺庙与庭院中常见的花木。",
    description: "鸡蛋花为落叶小乔木，高可达 8 m，树皮灰褐色，枝条粗壮肉质；叶片互生，长椭圆形，叶脉明显。花期 5–10 月，聚伞花序顶生，花冠漏斗状、5 裂，花瓣外面白色、内面基部黄色，形似鸡蛋，故得名，香气清雅；蓇葖果长角状，成熟时开裂，种子具翅，但栽培条件下少见结果。\n\n鸡蛋花原产墨西哥、中美洲及南美洲北部，中国广东、广西、福建、海南、云南等地栽培，喜高温多湿、光照充足，耐旱、不耐寒，适宜疏松肥沃、排水良好的土壤。花可提取香精，用于制作化妆品与高级香水；花可泡茶、晒干入药，有清热利湿之效；树皮与乳汁有一定毒性，需注意。鸡蛋花在老挝被视为国花，在东南亚佛教寺庙中常被种植，是热带地区极具代表性的观赏花木。",
