    description: "软枝黄蝉为常绿蔓性灌木，茎柔软、长可达数米，常攀援或匍匐生长；叶片对生或轮生，长椭圆形至倒卵形，革质有光泽。花期 5–10 月，聚伞花序顶生，花冠漏斗状、明黄色，花径 8–12 cm，花瓣 5 裂、边缘波状；蒴果球形，具刺，成熟时开裂，但栽培条件下少见结实。\n\n软枝黄蝉原产巴西、秘鲁等南美洲热带地区，中国广东、广西、福建、海南、云南等地栽培，喜高温多湿、光照充足，适宜疏松肥沃、排水良好的土壤，不耐寒。因花色明黄、花大而美、花期长，常被用于南方庭院、公园与棚架的立体绿化，也可盆栽观赏；全株含白色乳汁，有毒，误食会引起呕吐与腹泻，修剪时需注意防护。软枝黄蝉与黄蝉同属，前者枝条柔软蔓生、花大，后者植株较矮、花较小。",
