    description: "红千层为常绿灌木或小乔木，高可达 3 m，树皮灰褐色，枝条坚硬直立；叶片披针形，革质，坚硬，长 5–10 cm，揉碎后有清香。花期 5–6 月，穗状花序顶生，形似瓶刷，由多数雄蕊组成，雄蕊鲜红色、长而密集，花后枝条继续延伸并长出新叶；蒴果木质、杯状，紧贴枝条排列，可宿存多年。\n\n红千层原产澳大利亚东部，中国广东、广西、福建、海南、云南等地栽培，喜高温多湿、光照充足，适宜疏松肥沃、排水良好的酸性土壤，耐旱、不耐寒。因花序形似红色瓶刷、花开繁茂，是南方城市与庭院中极具特色的观花灌木，常用于公园、道路与庭院的绿化，也可作切花；叶片可提取芳香油。红千层与同属的串钱柳外形相似，但红千层枝条硬挺、花序较短，串钱柳枝条下垂、花序细长。",
