    description: "沙棘为落叶灌木或小乔木，高可达 5 m，枝条具刺；叶片互生，线状披针形，背面银白色。花期 4–5 月，花小、黄绿色，先花后叶，风媒传粉；果实为浆果状核果，橙黄色或橙红色，球形或椭圆形，直径 5–8 mm，密集着生于枝条上，果期 8–10 月，可在树上越冬。\n\n沙棘分布于中国西北、华北及西南的高原与干旱地区，也见于欧洲、中亚，喜光、耐寒、耐旱、耐盐碱、耐瘠薄，根系发达，可固氮。果实富含维生素 C、维生素 E 与多种生物活性物质，可制果汁、果酱与沙棘油，是重要的生态经济树种；沙棘林能防风固沙、保持水土，是黄土高原与荒漠化地区生态治理的先锋植物。沙棘的刺与酸性果实需注意采摘方式，嫩枝叶可作饲料。",
