    description: "碧桃为蔷薇科李属落叶小乔木，高 3–8 米，树皮灰褐色，小枝红褐色。叶片椭圆状披针形，边缘具细锯齿。花单生或两朵并生，重瓣，花瓣层层叠叠，有粉红、深红、白色及复色等，花径 4–6 厘米，花期 3–4 月，先花后叶或花叶同放；果实为核果，观赏品种结果少而小，果期 6–8 月。\n\n碧桃是桃的观赏变型，原产中国，栽培历史可追溯到两千多年前，《诗经》中已有“桃之夭夭，灼灼其华”的句子。它喜光、耐寒、耐旱，适宜疏松肥沃、排水良好的沙壤土，忌积水。碧桃品种繁多，有红花碧桃、白花碧桃、洒金碧桃、垂枝碧桃等，常植于公园、庭院与行道旁，北京植物园、上海南汇的桃花节都以碧桃为主角。桃胶可食用，桃木在民间被认为有辟邪之意。",
