    description: "海棠花为蔷薇科苹果属落叶小乔木，高 5–8 米，树皮灰褐色、光滑，小枝粗壮。叶片互生，椭圆形至长圆形，边缘具细锯齿，幼叶被柔毛。花 4–6 朵簇生，花蕾深红，开放后花瓣粉红至白色，倒卵形，花径 3–5 厘米，花期 4–5 月；果实近球形，黄色至红色，果期 8–9 月。\n\n海棠花原产中国，河北、山东、陕西、江苏、浙江等地有分布，栽培历史逾千年，与西府海棠、垂丝海棠、贴梗海棠并称“海棠四品”。它喜光、耐寒、耐旱，适宜深厚肥沃、排水良好的土壤。海棠花姿潇洒、花开似锦，古人常植于庭院，苏轼有“只恐夜深花睡去，故烧高烛照红妆”之句；果实可食但酸涩，多用于加工。海棠也是苹果嫁接的优良砧木。",
