    description: "紫叶小檗为小檗科小檗属落叶灌木，高 1–2 米，枝细密，具叶刺。叶片倒卵形或匙形，全缘，生长期呈紫红色至紫褐色，秋季转深红。花小，黄色，2–5 朵簇生，花期 4–5 月；浆果椭圆形，成熟时鲜红，果期 8–10 月。\n\n紫叶小檗原产日本，中国南北各地广泛栽培，是园林中重要的彩叶灌木。它喜光、耐寒、耐旱，也耐半阴，对土壤要求不严，耐修剪，常与金叶女贞、大叶黄杨等搭配组成色块与绿篱。秋季叶色转为深红，可一直保持到落叶。根与茎含小檗碱，可提取黄连素，入药有清热燥湿之效。春季黄花与紫叶相衬，秋季红果挂枝，观赏期长；因枝上有刺，也常作边界防护植物。",
