    description: "阔叶十大功劳为小檗科十大功劳属常绿灌木，高 1–4 米，茎粗壮，树皮灰褐色。奇数羽状复叶，小叶 7–15 枚，卵形至宽卵形，较十大功劳更宽大，革质，边缘具粗刺齿。花黄色，组成顶生的总状花序，花期 9–11 月；浆果卵形，成熟时蓝紫色、被白粉，果期翌年 3–5 月。\n\n阔叶十大功劳原产中国陕西、甘肃、河南、安徽、浙江、江西、福建、湖北、湖南、四川等地，生于海拔 1000–2000 米的山坡林下与灌丛。它喜光，也耐阴，喜温暖湿润，适宜深厚肥沃、排水良好的土壤。根、茎、叶含小檗碱，可入药，有清热解毒之效。叶形宽大、叶色浓绿，深秋黄花成串，冬季蓝果累累，是庭院与林下绿化的优良材料。",
