    description: "荚蒾为忍冬科荚蒾属落叶灌木，高 2–3 米，树皮灰褐色，小枝被短柔毛。叶片对生，宽倒卵形至椭圆形，边缘具齿，表面被糙毛。复伞形式聚伞花序，花小，白色，花期 5–6 月；核果椭圆形，成熟时鲜红，果期 9–11 月。\n\n荚蒾原产中国华北、华东、华中至西南各地，朝鲜半岛、日本也有分布，生于山坡林下与灌丛。它喜光，也耐半阴，耐寒、耐瘠薄，对土壤要求不严。春季白花满枝，秋季红果累累，是优良的观花观果灌木，常植于庭院、林缘与草坪边缘。果实酸甜，可少量食用或用于加工，但不宜多食；根、茎与叶可入药，有清热解毒、祛瘀消肿之效。",
    habitat: "海拔 2000 米以下的山坡林下、灌丛与沟谷，喜光也耐半阴",
    distribution: "中国华北、华东、华中至西南；朝鲜半岛、日本有分布",
    conservation: "暂无评估；中国未列入国家重点保护野生植物名录",
