    description: "六道木为忍冬科六道木属落叶灌木，高 1–2 米，幼枝红褐色，老枝具六条明显纵棱，故名六道木。叶片对生，长卵形至披针形，边缘疏生锯齿。花常两朵并生于叶腋，花冠钟状，淡粉色至白色，花期 5–6 月；果实为瘦果状核果，弯曲，具宿存萼片，果期 8–9 月。\n\n六道木原产中国华北、东北及西北山地，生于海拔 1000–2000 米的山坡灌丛与林缘。它喜光，也耐半阴，耐寒、耐旱、耐瘠薄，适宜排水良好的砂质壤土。枝条坚韧，可制手杖与工艺品；花期花量繁密，常植于庭院、岩石园与花篱。民间以茎枝入药，有祛风湿、消肿毒之效。花期长达月余，也是北方山地夏季重要的蜜源植物。",
