    description: "接骨木为忍冬科接骨木属落叶灌木，高 3–5 米，老枝有皮孔，髓部白色。叶对生，奇数羽状复叶，小叶 5–7 枚，卵形至长圆形，边缘具锯齿。伞房状聚伞花序顶生，花小，白色至淡黄色，花期 5–6 月；果实为浆果状核果，球形，成熟时红色，果期 8–9 月。\n\n接骨木原产中国东北、华北、华东至西南各地，生于山坡林下、溪边和村旁。它喜光，也耐半阴，耐寒、耐旱，对土壤要求不严。夏季白花满树，秋季红果累累，是观花观果兼用的乡土灌木；茎枝入药称“接骨木”，有祛风利湿、活血止痛之效，但果实与茎叶含少量毒性成分，不可随意食用。接骨木也是城市公园中常见的观果灌木。",
