    description: "虎刺梅为大戟科大戟属多浆灌木，高 30–100 厘米，茎直立，多分枝，具棱，棱上密生硬刺。叶互生，倒卵形至匙形，肉质，常生于嫩枝顶端，早落。杯状聚伞花序生于枝顶，总苞片鲜红色，形似花瓣，花期全年，以春夏最盛；果实为蒴果，但栽培条件下很少结果。\n\n虎刺梅原产马达加斯加，中国各地广泛盆栽，喜阳光充足、温暖干燥的环境，耐旱、怕积水，不耐寒。它茎上密生硬刺，红色苞片经久不落，是常见的室内外盆栽观赏植物；园艺品种有白、粉、黄等苞片颜色。乳汁有毒，接触皮肤会引起红肿，误食可致呕吐腹泻，修剪时应戴手套并避免儿童与宠物接触，冬季需保持 10℃ 以上。",
