    description: "茶梅为山茶科山茶属常绿灌木，高 1–3 米，嫩枝被短柔毛。叶互生，椭圆形至倒卵形，革质，边缘具细锯齿，表面深绿色、有光泽。花单生或 2–3 朵生于枝顶，花瓣 5–7 枚，白色、粉红色至红色，花径 4–7 厘米，花期 10 月至翌年 2 月；果实为蒴果，球形，果期翌年秋季。\n\n茶梅原产日本，中国长江以南广泛栽培，喜温暖湿润、半阴的环境，不耐强光暴晒，适宜疏松肥沃、排水良好的酸性土壤。它花期正值秋冬少花季节，花量繁密、花色柔和，凋谢时花瓣一片片散落，是南方庭院、绿篱与盆栽的常见花木。栽培以扦插和嫁接繁殖为主，需注意防治炭疽病与介壳虫，浇水宜用雨水或晾晒后的自来水。",
