    description: "金花茶为山茶科山茶属常绿灌木或小乔木，高 2–6 米，树皮灰褐色，嫩枝无毛。叶互生，椭圆形至长椭圆形，革质，边缘具细锯齿。花单生或 2 朵并生于叶腋，花瓣 8–12 枚，金黄色，蜡质光亮，花径 5–8 厘米，花期 11 月至翌年 3 月；果实为蒴果，扁球形，果期翌年秋季。\n\n金花茶原产中国广西南部及越南北部，生于海拔 100–500 米的沟谷林下，是中国特有的珍稀山茶，被誉为“茶族皇后”。它喜温暖湿润、半阴的环境，不耐强光暴晒和严寒，适宜疏松肥沃、排水良好的酸性土壤。金花茶花色金黄、花瓣蜡质，在山茶属中极为罕见，观赏价值极高；叶可制茶，花可入药。因野生资源稀少，被列为国家二级重点保护野生植物。",
