    summary: "蔷薇科落叶灌木，夏季开粉红色伞房花序，枝条细密、花量繁密，耐寒耐湿，是北方湿地与庭院常见的观花灌木。",
    description: "绣线菊为蔷薇科绣线菊属落叶灌木，高 1–2 米，枝条细长，幼枝被短柔毛。叶互生，披针形至长圆状披针形，边缘具尖锐锯齿。伞房花序顶生，花小，粉红色至淡紫红色，花期 6–8 月；果实为蓇葖果，果期 8–9 月。\n\n绣线菊原产中国东北、华北及朝鲜半岛、日本、俄罗斯远东地区，生于溪边、湿地与林缘。它喜光，也耐半阴，耐寒、耐湿，适宜疏松肥沃、排水良好的土壤。枝条细密、花量繁密，夏季粉花成片，是北方湿地与庭院常见的观花灌木；也常植于水岸与花境。栽培以分株和扦插繁殖为主，花后修剪可促进新枝萌发，冬季无需特殊防寒，是北方低维护的观花灌木。",
    habitat: "溪边、湿地、林缘与庭院，喜光耐湿",
    distribution: "中国东北、华北；朝鲜半岛、日本、俄罗斯远东地区",
    conservation: "暂无评估；中国未列入国家重点保护野生植物名录",
