    description: "木香为蔷薇科蔷薇属常绿攀援灌木，高可达 6 米，枝条细长、光滑，具少数皮刺。叶互生，奇数羽状复叶，小叶 3–5 枚，椭圆状卵形，边缘具细锯齿。伞形花序顶生，花小，白色或黄色，花瓣 5 枚，香气清雅，花期 4–5 月；果实为蔷薇果，球形，果期 9–10 月。\n\n木香原产中国西南至华中地区，生于山坡灌丛与溪边，各地庭院广泛栽培。它喜光，也耐半阴，喜温暖湿润，适宜疏松肥沃、排水良好的土壤。枝条细长、攀援力强，春季花量繁密，白花如雪、黄花如金，是庭院棚架、花墙与篱垣的优良材料；花可提取芳香油，根皮可入药。栽培以扦插和压条繁殖为主，需设支架供其攀爬，花后修剪可促进来年花枝发育。",
