    description: "金叶女贞为木犀科女贞属半常绿灌木，是金边女贞与欧洲女贞的杂交种，高 1–2 米，枝条细密。叶对生，卵形至椭圆形，新叶金黄色，老叶黄绿色，全缘。圆锥花序顶生，花小，白色，花期 5–6 月；果实为核果，椭圆形，成熟时紫黑色，果期 8–10 月。\n\n金叶女贞原产欧洲，中国各地园林广泛栽培，喜光，也耐半阴，耐寒性一般，适宜疏松肥沃、排水良好的土壤。它叶色金黄、耐修剪，是城市绿化中常见的彩叶绿篱材料，常与紫叶小檗、红叶石楠等配植成色块。栽培以扦插繁殖为主，需定期修剪以保持叶色鲜艳；光照不足时叶片易转绿，冬季寒冷地区可能出现落叶。",
    habitat: "城市绿地、道路绿篱与庭院，喜光也耐半阴",
