    description: "珊瑚树为忍冬科荚蒾属常绿灌木或小乔木，高 2–10 米，树皮灰褐色，枝条粗壮。叶对生，椭圆形至长圆形，革质，表面深绿色、有光泽，边缘具浅齿。圆锥花序顶生，花小，白色，花期 5–6 月；果实为核果，椭圆形，成熟时红色，后转黑色，果期 9–11 月。\n\n珊瑚树原产中国华南、华东及西南地区，日本、印度也有分布，生于山坡林下与溪边。它喜光，也耐半阴，喜温暖湿润，不耐严寒，适宜疏松肥沃、排水良好的土壤。枝叶茂密、耐修剪、抗污染，是南方常见的绿篱与防护林树种；秋季红果累累，也可作观果树种。栽培以扦插繁殖为主，北方盆栽冬季需移入室内。",
