    description: "云锦杜鹃为杜鹃花科杜鹃属常绿灌木或小乔木，高可达三至四米，树皮灰褐色，幼枝绿色。叶片互生，厚革质，长椭圆形至倒披针形，表面深绿有光泽，背面淡绿色。花六至十二朵组成顶生的伞形总状花序，花冠漏斗状钟形，淡粉色至白色，内面有紫红色斑点，花期四至五月；蒴果长圆柱形，成熟时褐色开裂，果期九至十月。\n\n云锦杜鹃是中国特有的高山杜鹃，分布于浙江、安徽、江西、福建、湖南、广西、贵州等地，多生于海拔八百至一千八百米的山地林中。它喜凉爽湿润、云雾缭绕的环境，要求酸性腐殖质土壤，耐寒而不耐高温。浙江天台山华顶山保存有大面积野生云锦杜鹃林，每年五月花开如云似锦，形成著名的花海景观。花大色雅，也可引种作高山园林观赏植物。",
