    description: "高山杜鹃为杜鹃花科杜鹃属常绿矮小灌木，高十至五十厘米，分枝匍匐或斜升，幼枝密被鳞片和短毛。叶片互生，小型，椭圆形至倒卵形，革质，表面深绿，背面密被褐色鳞片。花两至五朵簇生于枝顶，花冠漏斗状，紫红色至淡紫色，花期六至七月；蒴果小，卵圆形，成熟时褐色开裂，果期八至九月。\n\n高山杜鹃呈环北极分布，见于中国东北、内蒙古、新疆的高山地带以及北欧、北美和俄罗斯西伯利亚的苔原地区，多生于海拔两千米以上的高山冻原和岩缝中。它耐严寒、抗强风，植株低矮匍匐以抵御风雪，适宜酸性贫瘠土壤。花期虽短，但成片开放时把苔原染成紫红色，是北极和高山生态系统中的重要蜜源植物，也是研究植物对极端环境适应的材料。",
