    taxonomy: { phylum: "被子植物门", class: "木兰纲", order: "桃金娘目", family: "桃金娘科", genus: "红千层属" },
    summary: "桃金娘科红千层属常绿小乔木，枝条柔软下垂，红色穗状花序形似瓶刷，盛花时如串串红钱垂挂，十分醒目。",
    description: "串钱柳为桃金娘科红千层属常绿小乔木或灌木，高可达五至十米，树皮灰褐色、纵裂，枝条细长柔软、下垂如柳。叶片互生，革质，披针形，全缘，表面深绿。花组成顶生的穗状花序，雄蕊多数、鲜红色，长伸于花外，形似瓶刷，花期五至八月；蒴果木质，紧贴花序轴排列成串，形似一串铜钱，果期秋冬季。\n\n串钱柳原产澳大利亚昆士兰州，中国广东、广西、福建、海南、云南等地有栽培。它喜高温湿润和充足阳光，不耐寒，适宜疏松肥沃、排水良好的土壤。枝条下垂、花色鲜红，是优良的观花乔木，常植于水边、庭院和道路两旁；因蒴果紧贴枝条排成串，形如串钱，故得名串钱柳。花富含花蜜，是蜜蜂和鸟类的重要蜜源。",
    habitat: "热带亚热带河岸与庭院，喜高温湿润、阳光充足",
    distribution: "原产澳大利亚昆士兰州；中国广东、广西、福建、海南、云南栽培",
    conservation: "暂无评估；中国未列入国家重点保护野生植物名录",
    details: [
      { label: "株高", value: "5–10 m，枝条下垂" },
      { label: "花期", value: "5–8 月，穗状花序鲜红" },
      { label: "果期", value: "秋冬季，蒴果串状" },
      { label: "光照", value: "极喜光，全日照开花盛" },
      { label: "水分", value: "喜湿润，耐短期积水" },
      { label: "土壤", value: "疏松肥沃的壤土" },
      { label: "主要用途", value: "水边观花树、行道树" }
    ],
    facts: [
      "串钱柳的雄蕊细长鲜红，聚成穗状，形状像洗瓶子的毛刷，故又名瓶刷树。",
      "它的蒴果紧贴枝条排成一串，老果经久不落，像一串串铜钱。",
      "串钱柳原产澳大利亚，花期时吸蜜的鸟类和蜜蜂络绎不绝。"
    ],
    tags: ["桃金娘科", "串钱柳", "观花乔木", "澳洲原产"]
