    description: "金银忍冬为忍冬科忍冬属落叶灌木，高可达两至三米，树皮灰褐色，小枝中空。叶片对生，卵状椭圆形至卵状披针形，全缘，表面深绿，背面淡绿。花成对生于叶腋，花冠二唇形，初开时白色，后渐变为黄色，花期五至六月，具香气；浆果球形，成熟时鲜红色，果期九至十月。\n\n金银忍冬分布于中国东北、华北、华东、华中及西北东部，朝鲜、日本、俄罗斯远东也有，多生于林缘、溪边和灌丛中。它喜光也耐半阴，耐寒、耐旱，对土壤要求不严。花白黄相间、香气清雅，秋季红果晶莹，是北方园林中观花观果兼用的灌木；花是优良的蜜源，果实可提取色素，茎皮纤维可制绳。金银忍冬与金银花同属，但花较小、果为红浆果。",
