    description: "香桃木为桃金娘科香桃木属常绿灌木，高一至三米，分枝密集，小枝具四棱。叶片对生，革质，卵状披针形，全缘，表面深绿有光泽，揉碎后有浓郁的芳香。花单生于叶腋，花冠白色，花瓣五枚，雄蕊多数，花期五至七月；浆果椭圆形，成熟时蓝黑色，表面被白粉，果期九至十一月。\n\n香桃木原产地中海沿岸、北非和西亚，中国南方有引种栽培。它喜温暖湿润和充足阳光，耐旱、耐修剪，适宜疏松肥沃、排水良好的石灰质土壤，不耐严寒。枝叶含挥发油，可提取香精用于化妆品和食品；干燥枝叶是地中海料理的调味香料；果实可食。花白果蓝、叶色常绿，也常作绿篱和盆栽观赏。在希腊神话中，香桃木被视为爱与美的象征。",
    habitat: "地中海沿岸的干燥山坡与灌丛，喜光耐旱、耐修剪",
