    description: "大叶冬青为冬青科冬青属常绿乔木，高可达十米，树皮灰褐色，小枝粗壮。叶片互生，厚革质，长椭圆形至披针形，大型，边缘具细锯齿，表面深绿有光泽。花单性，雌雄异株，花小，黄绿色，簇生于叶腋，花期四至五月；核果球形，成熟时鲜红色，果期十至十二月。\n\n大叶冬青分布于中国江苏、浙江、安徽、江西、福建、广东、广西、云南等地，多生于海拔五百至一千五百米的山地林中。它喜温暖湿润和半阴环境，适宜深厚肥沃、排水良好的酸性土壤。叶片宽大厚实、四季常青，可作庭园观赏树；嫩叶经加工可制苦丁茶，味苦回甘，是南方传统的保健饮品；木材细致，可制器具。红果经冬不落，也是冬季观果的优良树种。",
