    summary: "锦葵科木槿属落叶灌木，花淡黄色、花心暗红，耐盐碱抗海风，是浙江沿海沙地和海涂绿化的优良树种。",
    description: "海滨木槿为锦葵科木槿属落叶灌木，高一至三米，树皮灰褐色，嫩枝被星状毛。叶片互生，近圆形至宽卵形，边缘具细锯齿，表面粗糙，背面被灰白色绒毛。花单生于叶腋，花冠淡黄色，花瓣五枚，花心暗红色，花期六至九月；蒴果卵圆形，成熟时褐色开裂，果期九至十一月。\n\n海滨木槿分布于中国浙江、江苏沿海以及日本、朝鲜半岛的海岸，多生于海边沙地、盐碱地和潮间带上缘。它极耐盐碱、抗海风，耐旱也耐短期水淹，适宜疏松的砂质土壤。花淡黄、花心暗红，夏季开放，是沿海地区少有的观花灌木；树皮纤维可制绳和造纸。由于能固沙护堤、改良盐碱地，海滨木槿被视为海岸防护林和滨海湿地修复的优良树种。",
    habitat: "海岸沙地、盐碱地与潮间带上缘，极耐盐碱、抗海风",
    distribution: "中国浙江、江苏沿海；日本、朝鲜半岛海岸",
    conservation: "暂无评估；野生种群受沿海开发影响，部分地区加以保护",
