    description: "木本曼陀罗为常绿灌木或小乔木，高 2–4 米，茎干粗壮、多分枝，幼枝被短柔毛。叶片卵形至宽卵形，长 15–30 厘米，边缘全缘或波状，揉碎有特殊气味。花单生于叶腋、下垂，花冠喇叭状，白色，长 15–20 厘米，夜间香气最浓；果实纺锤形，表面光滑，成熟后开裂。\n\n本种原产南美洲安第斯山区，喜温暖湿润、阳光充足的环境，在中国南方常作庭园观赏植物栽培。它的花大而优雅，英文称“天使喇叭”，但全株含有东莨菪碱、莨菪碱等托品烷类生物碱，花、叶、果实与种子均有剧毒，误食可引起口干、心悸、幻觉、抽搐甚至死亡，汁液接触眼睛也会造成伤害。它仅供专业栽培观赏，不可自行采食或药用，家庭种植需远离儿童与宠物。",
    habitat: "热带与亚热带高原，喜温暖湿润、阳光充足，不耐寒",
    distribution: "原产南美安第斯山区；中国华南、西南及世界各地热带地区引种栽培",
    conservation: "IUCN 暂无评估；栽培广泛，野生种群状况不明",
