    description: "鸳鸯茉莉为常绿灌木，高 1–2 米，分枝密集，茎皮灰褐色。叶片椭圆形至倒卵形，长 5–10 厘米，革质，上面深绿色。花单生或数朵聚生叶腋，花冠高脚碟状，初开时蓝紫色，随后逐渐褪为淡紫、白色，同一株上可见紫、白两色花并存，直径约 4–5 厘米，芳香浓郁；果实为浆果状，成熟时橙黄色。\n\n本种原产巴西热带地区，喜温暖湿润、阳光充足的环境，在中国华南、西南常作盆栽或庭园花木。它花期长、香气浓，因花色由紫变白、宛如“昨日、今日、明日”而得名英文 Yesterday-today-tomorrow。全株含布鲁氏碱等生物碱，误食叶片或果实可引起流涎、呕吐、震颤等中毒症状，对猫狗尤其危险，观赏时应避免儿童与宠物啃食。",
