      "它的花丝远远伸出花冠，像火焰中迸出的火星，十分醒目。",
      "在华南寺庙中，赪桐常被当作吉祥花木种植，花期正值盛夏。",
      "赪桐的根和叶在民间入药，用于清热利湿、散瘀消肿。"
