    description: "粉花凌霄为常绿藤状灌木，蔓长可达 5–8 米，茎干柔韧，靠卷须状的气生根攀援。叶对生，奇数羽状复叶，小叶 7–11 枚，卵形至披针形，边缘具锯齿。圆锥花序顶生，花冠漏斗状，粉红色，长 6–8 厘米，喉部具紫红色条纹，花冠檐部 5 裂，花期繁密；蒴果长条形，成熟时开裂，种子具翅。\n\n本种原产南非，喜温暖湿润、阳光充足的环境，在中国华南、西南常作棚架、篱垣与坡面绿化。它花大色柔、开花繁盛，一朵花可开数日，整株花期可达半年，是南方藤本花木中的佼佼者。粉花凌霄不耐寒，长江以北需温室盆栽；生长迅速，需定期修剪控制冠幅，并设坚固支架承受花量。其花蜜丰富，能吸引蜜蜂与蝴蝶。",
