    description: "金露花为常绿灌木，高 2–3 米，枝细长，常下垂，具刺。叶片对生，卵状披针形，长 3–7 厘米，边缘有锯齿。总状花序顶生或腋生，花冠蓝紫色，边缘白色，直径约 2 厘米，花冠筒略弯，花期长；核果球形，成熟时橙黄色，成串下垂，形似金色露珠。\n\n本种原产热带美洲，喜温暖、阳光充足的环境，耐修剪、耐旱，在中国华南常作绿篱、造型灌木与观果植物。它花果俱美，蓝花与金果同株，全年可多次开花。需要注意的是，金露花的果实与叶片含有毒生物碱，误食可引起呕吐、腹泻与神经系统症状，儿童与宠物应避免接触。其枝条带刺，栽植时需留出通行空间。在华南，它常被修剪成方形或球形绿篱。",
